-- Root: BEGIN + exact helper + fixture. Only synthetic review/clearing rows in rollback; zero source requests.
CREATE TEMP TABLE ctx07_successor_test_v7(receipt jsonb) ON COMMIT DROP;
DO $test$
DECLARE h text;r jsonb;again jsonb;before_counters jsonb;after_counters jsonb;verified integer;unsupported integer;proof jsonb;source_hash text;output_hash text;commit_ref uuid;BEGIN
 PERFORM population_top3000_202608_202609_v1.continuation_guard_v6('top3000-completion-20261024-root-5db48b32d103',3,1);
 h:=encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.ctx07_emit_source_successors_v7(text,bigint,bigint)'::regprocedure),'UTF8')),'hex');
 SELECT jsonb_build_object('provider',provider_requests,'http',http_invocations,'stored',stored_bytes,'reserved',reserved_bytes,'deadline',p.deadline) INTO before_counters FROM population_top3000_202608_202609_v1.acquisition_control a CROSS JOIN population_top3000_202608_202609_v1.pipeline_control p WHERE a.singleton AND p.singleton;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('CTX07_V7_SUCCESSOR_DISPATCH_REVIEW',jsonb_build_object('approved',true,'reviewer','synthetic-independent-fixture','producer','synthetic-producer-fixture','code_commit',repeat('0',40),'helper_function_sha256',h,'synthetic_test_only',true));
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='CTX07_V6_COMPONENT_QUALIFICATION_REVIEW' AND details->>'source_id'='empsit_202607') THEN RAISE EXCEPTION 'RUN_FIXTURE_BEFORE_PERSIST_QUALIFICATION';END IF;
 SELECT b.raw_sha256 INTO source_hash FROM population_top3000_202608_202609_v1.ctx07_recovery_body_v6 b JOIN population_top3000_202608_202609_v1.ctx07_recovery_request_v6 req USING(request_key) WHERE req.source_id='empsit_202607';
 SELECT c.output_sha256,c.commit_id INTO output_hash,commit_ref FROM population_top3000_202608_202609_v1.pipeline_commit c JOIN population_top3000_202608_202609_v1.pipeline_task t USING(task_id) WHERE t.stage='NORMALIZE' AND t.partition_key='ctx07-recovery-v6:empsit_202607:'||source_hash AND c.new_committed_units>0;
 proof:=jsonb_build_object('decision','QUALIFIED_COMPONENT_RECONSTRUCTION_WITH_REQUIRED_REVISION_HOLD','reviewer','synthetic-independent-fixture','producer','synthetic-producer-fixture','source_id','empsit_202607','source_sha256',source_hash,'output_sha256',repeat('0',64),'live_evidence_hashes_all_recomputed',true,'source_body_independently_rehashed_live',true,'original_lexical_numeric_and_publication_headers_independently_rechecked',true,'evidence_status_counts',jsonb_build_object('NUMERICAL_PUBLICATION_RECONSTRUCTION_VERIFIED',3),'strict_original_receipt_qualified',false,'family_accepted',false,'useful_commit_id',commit_ref,'synthetic_test_only',true);
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('CTX07_V6_COMPONENT_QUALIFICATION_REVIEW',proof);
 r:=population_top3000_202608_202609_v1.ctx07_emit_source_successors_v7('top3000-completion-20261024-root-5db48b32d103',3,1);
 IF (r->>'new_assignments')::integer NOT BETWEEN 1 AND 16 THEN RAISE EXCEPTION 'NO_BOUNDED_CONCRETE_ASSIGNMENTS %',r;END IF;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.continuation_clear_queue_v6 WHERE clearing_id LIKE 'ctx07-source-v7:%' AND kind='INDEPENDENT_VERIFICATION' AND input_manifest->0->>'source_id'='empsit_202607' AND status='COMPLETE') THEN RAISE EXCEPTION 'WRONG_REVIEW_HASH_ACCEPTED';END IF;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('CTX07_V6_COMPONENT_QUALIFICATION_REVIEW',jsonb_set(proof,'{output_sha256}',to_jsonb(output_hash)));
 again:=population_top3000_202608_202609_v1.ctx07_emit_source_successors_v7('top3000-completion-20261024-root-5db48b32d103',3,1);
 IF (again->>'new_assignments')::integer<>0 THEN RAISE EXCEPTION 'DUPLICATE_SUCCESSOR_ASSIGNMENT';END IF;
 SELECT count(*) INTO verified FROM population_top3000_202608_202609_v1.continuation_clear_queue_v6 q CROSS JOIN LATERAL jsonb_array_elements(q.input_manifest->0->'observations')o WHERE q.clearing_id LIKE 'ctx07-source-v7:%' AND q.kind='INDEPENDENT_VERIFICATION' AND q.input_manifest->0->>'source_id'='empsit_202607' AND o->>'status'='NUMERICAL_PUBLICATION_RECONSTRUCTION_VERIFIED' AND q.status='COMPLETE';
 SELECT count(*) INTO unsupported FROM population_top3000_202608_202609_v1.continuation_clear_queue_v6 q CROSS JOIN LATERAL jsonb_array_elements(q.input_manifest->0->'observations')o WHERE q.clearing_id LIKE 'ctx07-source-v7:%' AND q.kind='IMPLEMENTATION_REPAIR' AND q.input_manifest->0->>'source_id'='empsit_202607' AND o->>'status'='EXTRACTION_RULE_REQUIRED' AND q.status='READY';
 IF verified<>3 OR unsupported<>1 THEN RAISE EXCEPTION 'JULY_SOURCE_UNIT_PARTITION_CHANGED';END IF;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.continuation_clear_queue_v6 q LEFT JOIN population_top3000_202608_202609_v1.pipeline_event e ON e.event_id=q.assignment_event_id WHERE q.clearing_id LIKE 'ctx07-source-v7:%' AND(e.event IS DISTINCT FROM 'ENGINEERING_IMPLEMENTATION_ASSIGNMENT_V5' OR e.details->>'new_provider_requests' IS DISTINCT FROM '0' OR e.details->>'input_sha256' IS DISTINCT FROM q.input_sha256 OR e.details->>'family_acceptance_authorized' IS DISTINCT FROM 'false')) THEN RAISE EXCEPTION 'CONCRETE_SUCCESSOR_MANIFEST_INVALID';END IF;
 BEGIN UPDATE population_top3000_202608_202609_v1.acquisition_control SET stop_generation=2 WHERE singleton;PERFORM population_top3000_202608_202609_v1.ctx07_emit_source_successors_v7('top3000-completion-20261024-root-5db48b32d103',3,1);RAISE EXCEPTION 'STOP_ACCEPTED';EXCEPTION WHEN raise_exception THEN IF SQLERRM IS DISTINCT FROM 'CONTINUATION_OWNER_STOP_SCOPE_CHANGED' THEN RAISE;END IF;END;
 BEGIN UPDATE population_top3000_202608_202609_v1.acquisition_control SET owner_id='changed' WHERE singleton;PERFORM population_top3000_202608_202609_v1.ctx07_emit_source_successors_v7('top3000-completion-20261024-root-5db48b32d103',3,1);RAISE EXCEPTION 'OWNER_ACCEPTED';EXCEPTION WHEN raise_exception THEN IF SQLERRM IS DISTINCT FROM 'CONTINUATION_OWNER_STOP_SCOPE_CHANGED' THEN RAISE;END IF;END;
 SELECT jsonb_build_object('provider',provider_requests,'http',http_invocations,'stored',stored_bytes,'reserved',reserved_bytes,'deadline',p.deadline) INTO after_counters FROM population_top3000_202608_202609_v1.acquisition_control a CROSS JOIN population_top3000_202608_202609_v1.pipeline_control p WHERE a.singleton AND p.singleton;
 IF before_counters IS DISTINCT FROM after_counters THEN RAISE EXCEPTION 'COUNTER_OR_DEADLINE_CHANGED';END IF;
 INSERT INTO ctx07_successor_test_v7 VALUES(jsonb_build_object('result','PASS_CTX07_V7_CONCRETE_SUCCESSORS','helper_function_sha256',h,'first_dispatch',r,'second_dispatch',again,'wrong_review_hash_rejected',true,'later_valid_review_reused',true,'verified_july_review_units',verified,'unsupported_july_parser_units',unsupported,'owner_stop_rejected',true,'counters_deadline_preserved',true,'external_requests',0,'production_changes_rolled_back',true));
END;$test$;
SELECT receipt FROM ctx07_successor_test_v7;
ROLLBACK;
